#!/usr/bin/env node
// Zero-dependency bundler that stitches the compiled `dist/*.js` ESM files
// into a single classic IIFE script. The output is loaded via plain
// `<script src="…">` (not `type="module"`) and is what we upload to
// `cdn.weights.chat/sdk/convbased-sdk.global.js`.
//
// We can get away with a naive concat because:
//  - There are no external runtime deps (only browser globals).
//  - All cross-file imports are `import { X } from "./Y"` against sibling
//    files we control.
//  - tsc's output keeps each declaration top-level, so collapsing them into
//    a shared IIFE scope works as long as we visit files in dependency order.

import { readFile, writeFile } from "node:fs/promises";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = fileURLToPath(new URL(".", import.meta.url));
const repoRoot = resolve(here, "..");
const distDir = resolve(repoRoot, "dist");
const outFile = resolve(distDir, "convbased-sdk.global.js");

// Dependency order — modules with no internal imports first.
const order = [
	"events.js",
	"sdp.js",
	"types.js",
	"endpoints.js",
	"auth.js",
	"errors.js",
	"graphql.js",
	"upload.js",
	"signalingTicket.js",
	"signaling.js",
	"rtcServers.js",
	"tts.js",
	"client.js",
	"convbased.js",
];

// Names re-exported from src/index.ts → assigned to window.Convbased. The bag
// itself is named `Convbased`, so listing the façade helpers here lets the
// script-tag build call `Convbased.startVoiceChange(…)` directly.
const globals = [
	"startVoiceChange",
	"convertFile",
	"textToSpeech",
	"ConvbasedClient",
	"TtsClient",
	"uploadAudio",
	"requestAudioUpload",
	"putToPresigned",
	"graphqlRequest",
	"applyOpusSdpOptions",
	"fetchRTCServers",
	"DEFAULT_STUN_SERVERS",
	"DEFAULT_SIGNALING_URL",
	"DEFAULT_GRAPHQL_URL",
	"RTCStatusCode",
	"SdkAuthError",
	"SdkServiceError",
	"SdkAuthSession",
	"SignalingTicketError",
	"issueSignalingTicket",
	"signalingTicketUrl",
	"signalingWebSocketUrl",
];

// Strip every line that is purely an import / re-export. Convert
// `export <decl>` into a local declaration so the symbol stays in scope.
function rewrite(source) {
	const lines = source.split(/\r?\n/);
	const out = [];
	for (let i = 0; i < lines.length; i++) {
		const line = lines[i];

		// Drop sourcemap pragma — points at the per-file map which won't
		// resolve in the bundled output anyway.
		if (line.startsWith("//# sourceMappingURL=")) continue;

		// `import …` and `export … from "./…"` — strip entirely.
		if (/^\s*import\s/.test(line) || /^\s*export\s.*from\s/.test(line)) {
			// Multi-line import block? Skip until we see the closing line.
			if (!/;\s*$/.test(line) && !/from\s+["'][^"']+["'];?\s*$/.test(line)) {
				let j = i + 1;
				while (j < lines.length && !/from\s+["'][^"']+["'];?\s*$/.test(lines[j])) {
					j++;
				}
				i = j;
			}
			continue;
		}

		// `export class Foo` / `export function …` / `export const …` /
		// `export async function …` / `export var …` — strip the `export`.
		const indent = (line.match(/^\s*/) || [""])[0];
		const stripped = line.replace(
			/^\s*export\s+(default\s+)?(async\s+function|function|class|const|let|var|interface|type|enum)\s/,
			(_, _def, keyword) => indent + keyword + " ",
		);
		out.push(stripped);
	}
	return out.join("\n");
}

const banner = `/**
 * @convbased/sdk — bundled IIFE build.
 *
 * Auto-generated by scripts/bundle.mjs. Do not edit directly.
 *
 * Hosted at https://cdn.weights.chat/sdk/convbased-sdk.global.js — drop a
 * classic script tag and read symbols from window.Convbased:
 *
 *   <script src="https://cdn.weights.chat/sdk/convbased-sdk.global.js"></script>
 *   <script>
 *     const client = new Convbased.ConvbasedClient({ auth });
 *   </script>
 */`;

async function main() {
	const chunks = [];
	for (const name of order) {
		const path = resolve(distDir, name);
		const source = await readFile(path, "utf8");
		chunks.push(`// ===== ${name} =====`);
		chunks.push(rewrite(source));
	}

	const globalAssignments = globals
		.map((name) => `\t\t${name},`)
		.join("\n");

	const bundle = `${banner}
(function (globalThis) {
\t"use strict";
${chunks.join("\n\n")}

\tconst api = {
${globalAssignments}
\t};

\t// Expose as window.Convbased so consumers can do:
\t//   const client = new Convbased.ConvbasedClient({ auth });
\tif (typeof globalThis.Convbased === "undefined") {
\t\tglobalThis.Convbased = api;
\t} else {
\t\tObject.assign(globalThis.Convbased, api);
\t}
})(typeof globalThis !== "undefined" ? globalThis : window);
`;

	await writeFile(outFile, bundle, "utf8");
	console.log(
		`[bundle] wrote ${outFile} (${Buffer.byteLength(bundle).toLocaleString()} bytes)`,
	);
	console.log(
		`[bundle] upload this file to https://cdn.weights.chat/sdk/convbased-sdk.global.js`,
	);
}

main().catch((err) => {
	console.error("[bundle] failed:", err);
	process.exit(1);
});
